 31	    private static List<Integer> collectMatches(SearchState searchState) {
 32	        List<Integer> matches = new ArrayList<>(searchState.windowCount());
 33	        while (searchState.hasCurrentWindow()) {
 34	            if (searchState.isMatch()) {
 35	                matches.add(searchState.currentStart());
 36	            }
 37	            searchState.advance();
 38	        }
