163	    private static final class RollingHash {
164	        private RollingHash() {
165	        }
166	
167	        private static int compute(CharSequence value, int length) {
168	            int hash = 0;
169	            for (int i = 0; i < length; i++) {
170	                hash = (RADIX * hash + value.charAt(i)) % MODULUS;
171	            }
172	            return hash;
173	        }
174	
175	        private static int roll(
176	            int currentHash,
177	            char outgoingChar,
178	            char incomingChar,
179	            int highOrderMultiplier
180	        ) {
181	            int nextHash = (
182	                RADIX * (currentHash - outgoingChar * highOrderMultiplier) + incomingChar
183	            ) % MODULUS;
184	
185	            if (nextHash < 0) {
186	                nextHash += MODULUS;
187	            }
188	
189	            return nextHash;
190	        }
191	    }
