193	    private static int computeHighOrderMultiplier(int patternLength) {
194	        int highOrderMultiplier = 1;
195	        for (int i = 0; i < patternLength - 1; i++) {
196	            highOrderMultiplier = (highOrderMultiplier * RADIX) % MODULUS;
197	        }
198	        return highOrderMultiplier;
199	    }
